        .into_iter()
        .chain([SendMode::Code, SendMode::Both, SendMode::Spec])
        .map(|send| {
            let (label, sent_label, tooltip) = send_labels(send);
            let send_color = chat_input::mode_color(send, cx);
            let (button, sent) = action_button(
