                } else {
                    IconName::ArrowRight
                })
                .label(if sent { sent_label } else { label })
                .tooltip(tooltip);
            if mode == Some(send) {
                // Light text on a dark colour, dark on a light one.
                let foreground = if send_color.l > 0.6 {
                    gpui_kit::black()
                } else {
                    gpui_kit::white()
                };
                button
                    .custom(
