                    // resting colour, so the colour is given to the button
                    // itself.
                    .bg(send_color)
                    .text_color(foreground)
                    .into_any_element()
            } else {
                button.ghost().text_color(send_color).into_any_element()
            }
        })
        .collect::<Vec<_>>();
    let card_box = card_box(id, color, cx)
        .child(
            h_flex()
                .gap_1p5()
                .text_xs()
                .font_medium()
                .text_color(color)
